node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

// Current time context: orders are from 2026-09-02, so let's use ~2026-09-09 for 'one week from now'
// 2026-09-02 was the order date. The existing reminders use creation_timestamp ~1788228000 (2026-09-01)
// 1788228000 = approx 2026-09-01. One week later = +604800
const now = 1788832800;  // ~2026-09-08 10:00 AM EST
const oneWeekLater = now + 604800;  // ~2026-09-15 10:00 AM EST
const reminderId = crypto.randomUUID();

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, '2026-09-08T10:00:00')
\`).run(
  reminderId,
  'Follow up on ORD-E0E671 exchange request for Aurora Smart Desk Lamp Pro. Check order delivery status and explore exchange/cancellation options.',
  now,
  oneWeekLater
);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('=== Reminder Created ===');
console.log(JSON.stringify(reminder, null, 2));
"

